import React, { useState } from 'react';

const mockEstudiantes = [
  { id: 1, apellidoPaterno: 'González', apellidoMaterno: 'Pérez', nombres: 'Juan Carlos', ci: '12345678' },
  { id: 2, apellidoPaterno: 'Rodríguez', apellidoMaterno: 'Lopez', nombres: 'María Fernanda', ci: '87654321' },
  { id: 3, apellidoPaterno: 'Martínez', apellidoMaterno: 'Gómez', nombres: 'Luis Alberto', ci: '11223344' },
  // Puedes agregar más datos de prueba
];

const ActualizarDatos = () => {
  const [searchTerm, setSearchTerm] = useState('');

  // Filtrar estudiantes según la búsqueda (por apellidos, nombres o CI)
  const filteredEstudiantes = mockEstudiantes.filter(({ apellidoPaterno, apellidoMaterno, nombres, ci }) => {
    const search = searchTerm.toLowerCase();
    return (
      apellidoPaterno.toLowerCase().includes(search) ||
      apellidoMaterno.toLowerCase().includes(search) ||
      nombres.toLowerCase().includes(search) ||
      ci.includes(search)
    );
  });

  const handleActualizarClick = (estudiante) => {
    alert(`Actualizar datos de: ${estudiante.nombres} ${estudiante.apellidoPaterno}`);
    // Aquí puedes redirigir o abrir modal para editar datos
  };

  return (
    <div>
      <h3 className="text-xl font-semibold mb-4">Actualizar Datos</h3>

      <input
        type="text"
        placeholder="Buscar estudiante por nombre o CI"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        className="mb-4 p-2 border border-gray-300 rounded w-full max-w-md"
      />

      <table className="min-w-full bg-white border border-gray-200 rounded">
        <thead>
          <tr className="bg-gray-100 text-left">
            <th className="py-2 px-4 border-b">Apellido Paterno</th>
            <th className="py-2 px-4 border-b">Apellido Materno</th>
            <th className="py-2 px-4 border-b">Nombres</th>
            <th className="py-2 px-4 border-b">CI</th>
            <th className="py-2 px-4 border-b">Acción</th>
          </tr>
        </thead>
        <tbody>
          {filteredEstudiantes.length > 0 ? (
            filteredEstudiantes.map((est) => (
              <tr key={est.id} className="hover:bg-gray-50">
                <td className="py-2 px-4 border-b">{est.apellidoPaterno}</td>
                <td className="py-2 px-4 border-b">{est.apellidoMaterno}</td>
                <td className="py-2 px-4 border-b">{est.nombres}</td>
                <td className="py-2 px-4 border-b">{est.ci}</td>
                <td className="py-2 px-4 border-b">
                  <button
                    onClick={() => handleActualizarClick(est)}
                    className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700"
                  >
                    Actualizar Datos
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" className="text-center py-4 text-gray-500">
                No se encontraron estudiantes.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default ActualizarDatos;
